record.field:
select = 0

formula = ''

formula2 = ''

for indicator_line in record.temp_structure_details:

  if (indicator_line.accounting_select == True):

    select += 1

    formula += "[" + indicator_line.charge_name + "]"



if select == 0:

 raise UserError("Atleast One Line Should be Selected.")



update_formula = env['structure_details'].search([('id', '=', record.temp_structure_details_id.id)],limit=1)

if update_formula:

  if update_formula.formula:

    formula2 = update_formula.formula + formula

  else:

    formula2 = formula



  update_formula.write({'formula':formula2})



if record.id:

  temp_rec = env['temp_structure_maste'].search([('id', '=', record.id)],limit=1)

  temp_rec.unlink()
